def select_next_node(graph, unvisited_nodes):
    eps = 1e-9
    pre = graph.graph.get('precomputed', {})
    max_core_k = pre.get('max_core_k', 1.0)

    clusterings = [graph.nodes[n]['clustering'] for n in unvisited_nodes]
    betws = [graph.nodes[n]['betweenness'] for n in unvisited_nodes]
    cores = [graph.nodes[n]['core_number'] for n in unvisited_nodes]

    def normalize(vals):
        mn, mx = min(vals), max(vals)
        if mx - mn < eps:
            return [0.5] * len(vals)
        return [(v - mn) / (mx - mn) for v in vals]

    clusterings_n = normalize(clusterings)
    betws_n = normalize(betws)
    cores_n = normalize(cores)

    def harmonic_mean(x, y):
        if x + y < eps:
            return 0.0
        return 2 * x * y / (x + y)

    best_score = -float('inf')
    best_node = None

    for i, n in enumerate(unvisited_nodes):
        hm = harmonic_mean(clusterings_n[i], 1 - betws_n[i])
        core_factor = math.exp(-cores_n[i] / (max_core_k + eps))
        score = hm * core_factor

        if score > best_score:
            best_score = score
            best_node = n

    return best_node

